import{S as d,o as s,c as r,a9 as a,B as c}from"./chunks/framework.DxG24V0C.js";const p=JSON.parse('{"title":"Capability 缝体系：为什么换一个实现能牵一发动全身","description":"","frontmatter":{"title":"Capability 缝体系：为什么换一个实现能牵一发动全身"},"headers":[],"relativePath":"deepseek/06-capability-seams.md","filePath":"deepseek/06-capability-seams.md","lastUpdated":1788319991000}'),n={name:"deepseek/06-capability-seams.md"},h=Object.assign(n,{setup(i){const e=[{question:'要完整地做出一个"能力"，最少要设计哪三种可独立演化的角色？',options:["接口、一个实现、一个开关","接口、一个实现、一段日志","实现、消费方、周边工具包","服务定义、服务实现、服务消费者"],correct:3,explanation:"capability 缝 = Service Definition + Provider + Consumer（后者一般是 model-facing tool）。只做其中一个角色不构成 seam。"},{question:"为什么 Consumer 只依赖服务接口（Service Definition）而不 import 具体 Provider？",options:["因为接口往往更短更好读","因为 import 一个包就会死循环","因为否则换 Provider 时 Consumer 也得改","因为 Provider 不对外暴露方法"],correct:2,explanation:'Consumer 只依赖服务接口、不 import 实现，所以换 Provider 时 Consumer 与整个产品都不动。这是"可换缝"成立的关键。'},{question:'"Provider 互换会整套移动" 最根本的原因是什么？',options:["多个缝往往共享同一个执行世界","新 Provider 通常代码量更少","因为产品只允许单进程","因为 Provider 决定 CPU 频率"],correct:0,explanation:'fs 与 subprocess 共享"执行世界"，bash/PTY/LSP 都经 ctx.subprocess 这条缝去 spawn，换一组 provider 时这些能力成套迁移、无分叉。'},{question:"seam 中 Service Definition 的职责，最匹配的是哪一项？",options:["定义接口、词汇、事件，并独立于实现","把接口与实现写进同一个包","只负责本地的具体落盘实现","生成给模型看的精确参数 schema"],correct:0,explanation:"Definition 定义接口与词汇并独立于后端；Provider 是具体实现；Consumer 才提供模型 schema——三者分工明确。"},{question:"`sandboxMode` 这个能力事实的作用是什么？",options:["它是仅供内部参考的调试标记","Provider 填一个事实，Consumer 据它决定是否暴露沙箱字段","它强制模型每步都必须用沙箱","它让所有工具天生都带沙箱"],correct:1,explanation:'Provider 在 `ctx.shell` 上填 `sandboxMode`；Consumer 读它来决定是否给工具 schema 加"要求沙箱"字段，而无需知道 bwrap/Landlock 等后端细节。'}];return(l,o)=>{const t=d("Quiz");return s(),r("div",null,[o[0]||(o[0]=a('<h1 id="capability-缝体系-为什么换一个实现能牵一发动全身" tabindex="-1">Capability 缝体系：为什么换一个实现能牵一发动全身 <a class="header-anchor" href="#capability-缝体系-为什么换一个实现能牵一发动全身" aria-label="Permalink to &quot;Capability 缝体系：为什么换一个实现能牵一发动全身&quot;">​</a></h1><blockquote><p>本文基于 <code>dsh-v0.1.0-rc.7</code>。项目处于 developer preview，迭代很快，文中机制以该基线为准。</p></blockquote><p>前五篇把 <code>dsh</code> 从&quot;插件森林&quot;一步步走到&quot;工具管线&quot;。第六篇触及它真正区别于终端 agent 的核心抽象：<strong>capability 缝（capability seam）</strong>。</p><p>先想一个硬问题。终端 agent 的代码里，&quot;执行 bash&quot;&quot;读写文件&quot;&quot;起一个子进程&quot;这些事<strong>通常是写死在各自的大类里</strong>：想给 bash 加隔离？改 bash 那个类。想搬到远程沙箱？改文件工具、改 shell 工具、改 LSP……到处都要动。<code>dsh</code> 不这么做。</p><p>它的答案是：把每个&quot;能力&quot;拆成<strong>可插换的三件套</strong>——<strong>Service Definition（接口声明）+ Service Provider（实现）+ Consumer（消费方，通常是模型面上工具）</strong>，三者通过 Cordis 的一个 <code>ctx.&lt;key&gt;</code> 连接起来。换一个实现，就只是<strong>换一个 Provider</strong>，三件套里其余两件毫发无损。</p><p>先放最硬的一句：</p><blockquote><p><strong>capability 缝 = (Service Definition / Service Provider / Consumer) 三件套。</strong> 只做其中一个角色不构成&quot;缝&quot;；一个能力被正确地做出来，意味着这三个角色都能独立演化、并被可逆地组装回一个可运行的 <code>ctx.&lt;key&gt;</code>。</p></blockquote><p><code>docs/capability-seams.md</code>（一份机器生成的图谱）把整个产品所有的 <code>ctx.*</code> 服务，按三种角色分类列出来——<code>core</code>（不可换的核心脊柱）、<code>seam</code>（可换的能力缝）、<code>bundle</code>（组合点）。下面我们一开始用 <code>seam</code> 展开。</p><h2 id="一、为什么需要三件套-把-接口-实现-用法-拆开" tabindex="-1">一、为什么需要三件套：把&quot;接口 / 实现 / 用法&quot;拆开 <a class="header-anchor" href="#一、为什么需要三件套-把-接口-实现-用法-拆开" aria-label="Permalink to &quot;一、为什么需要三件套：把&quot;接口 / 实现 / 用法&quot;拆开&quot;">​</a></h2><p>回顾第 2 篇，Cordis 的 Context 是&quot;服务仓库 + 键解耦&quot;。capability seam 就是<strong>这套模式最常见的产品化应用</strong>。三件套各自的职责：</p><table tabindex="0"><thead><tr><th>角色</th><th>职责</th><th>例子（bash）</th></tr></thead><tbody><tr><td><strong>Service Definition</strong></td><td>定义一个能力的<strong>抽象接口</strong>：能做什么、返回什么类型、暴露哪些事件。它<strong>依赖不了实现</strong>。</td><td><code>@deepseek-ai/dsh-shell</code>：<code>ctx.shell</code> 的接口与词汇（<code>run</code>/<code>start</code>/<code>sandboxMode</code>）</td></tr><tr><td><strong>Service Provider</strong></td><td>那个能力的<strong>具体实现</strong>。可以有多种；但同一时刻同层只有一个 provider 供组合。</td><td><code>@deepseek-ai/dsh-bash-local</code>（本地子进程）/ <code>dsh-bash-sandbox</code>（套 <code>ctx.sandbox</code> 的隔离执行器）</td></tr><tr><td><strong>Consumer</strong></td><td><strong>使用这个能力</strong>的一方，通常是 model-facing 的一个工具。</td><td><code>@deepseek-ai/dsh-tool-bash</code>：把 bash 能力暴露给模型</td></tr></tbody></table><p>看 <code>@deepseek-ai/dsh-shell</code> 的 README，它开头就把这个拆法摆在眼前：</p><blockquote><p>This package owns the <strong>Service Definition</strong> role of the bash capability, split so each role can evolve (and be swapped) independently.</p></blockquote><p>——&quot;拆分，正是为了让每个角色可以<strong>独立演化、独立换掉</strong>&quot;。这回答了一个关键问题：为什么接口要单独一个包？因为<strong>如果接口跟实现绑一起，你就无法在不改工具的前提下换掉实现</strong>；接口独立成包，Consumer（工具）永远只对着接口编程，Provider 换谁都不影响它。</p><p>于是我们得到 capability 缝的核心本事：<strong>一个能力 = 一个稳定的接口，被若干 Provider 实现、被 Consumer（工具）只通过接口访问；工具不 import 任何实现。</strong> 这是它和&quot;硬编码进 loop&quot;最本质的区别。</p><h2 id="二、-没有特权核心-与-capability-缝-一体的原因" tabindex="-1">二、&quot;没有特权核心&quot;与 capability 缝：一体的原因 <a class="header-anchor" href="#二、-没有特权核心-与-capability-缝-一体的原因" aria-label="Permalink to &quot;二、&quot;没有特权核心&quot;与 capability 缝：一体的原因&quot;">​</a></h2><p>前几篇反复说 <code>dsh</code> 没有特权核心。capability 缝正是那个&quot;没有特权核心&quot;<strong>在能力层的落地</strong>——因为一切能力都可换，就根本没有&quot;哪个能力是产品必须内置&quot;的说法。</p><p>想象一下，如果工具（Consumer）import 了 <code>dsh-bash-local</code> 这个 Provider 类，那么&quot;本地 bash&quot;就焊死在工具上了，你要换成远程执行器就得改工具。capability 缝避免了这一点：<strong>Consumer 只在构造期通过注入拿到 <code>ctx.shell</code> 服务，运行时只调 <code>ctx.shell.run(...)</code>。</strong> 因为注入的是接口（Service Definition），而不是实现，所以 Provider 换一次，Consumer 和整个产品都不动。</p><p>这里补一个&quot;为什么三件套，而不是两件（接口 + 实现）&quot;的探根：<strong>因为&quot;消费&quot;这个角色也需要独立演化</strong>。比如 <code>tool-bash</code> 作为 Consumer，它会读 Provider 暴露的 <code>sandboxMode</code> 这个&quot;能力事实&quot;来<strong>主动给模型加上&quot;要沙箱里的隔离&quot;的说明</strong>。可见 Consumer 不只是&quot;调接口&quot;，它还根据实现的能力做 UI/提示/安全上的适配——三件套里，三环都在各自的演化。</p><h2 id="三、逐个-seam-实例-把抽象落到四个真实缝" tabindex="-1">三、逐个 seam 实例：把抽象落到四个真实缝 <a class="header-anchor" href="#三、逐个-seam-实例-把抽象落到四个真实缝" aria-label="Permalink to &quot;三、逐个 seam 实例：把抽象落到四个真实缝&quot;">​</a></h2><h3 id="_1-bash-能力缝-ctx-shell" tabindex="-1">（1）bash 能力缝：<code>ctx.shell</code> <a class="header-anchor" href="#_1-bash-能力缝-ctx-shell" aria-label="Permalink to &quot;（1）bash 能力缝：`ctx.shell`&quot;">​</a></h3><p><code>@deepseek-ai/dsh-shell</code> 定义了 <code>ShellExecutor</code> 接口：它说&quot;<strong>WHAT</strong> a bash backend does（跑前台命令、起后台进程）——而不说 <strong>HOW</strong>&quot;。Provider 有多个：<code>dsh-bash-local</code>（本地子进程）、<code>dsh-bash-sandbox</code>（本地机制、每个 spawn 都由 <code>ctx.sandbox</code> 约束）；Consumer 是 <code>dsh-tool-bash</code>（把 <code>ctx.shell</code> 暴露给模型的工具）。</p><p>最妙的是 <code>sandboxMode</code> 这个<strong>能力事实</strong>：<code>dsh-shell</code> 的定义里 base class 的 <code>sandboxMode</code> 是 <code>undefined</code>（&quot;我不沙箱&quot;），而 <code>dsh-bash-sandbox</code> 这个 Provider 会把它填成默认模式。Consumer <code>dsh-tool-bash</code> 在注册时<strong>读取这个能力事实</strong>，只有 Composition 里有沙箱 provider 时，才把 &quot;要求沙箱&quot; 的字段加进模型工具 schema：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 来自 @deepseek-ai/dsh-tool-bash（简化）</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Provider 的 sandboxMode 定义了工具的加字段时机</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (shell.sandboxMode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> undefined</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 添加引导字段，让模型能要求 sandbox</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这印证了：&quot;Consumer 可以因 Provider 的能力而<strong>自我适配</strong>&quot;——换一个沙箱型的 shell 执行器，Consumer 会自动向模型多暴露一个&quot;请给我沙箱&quot;的开关，不需要 Consumer 知道 <code>bwrap</code> 还是 Landlock。</p><h3 id="_2-文件系统缝-ctx-fs-的四层栈" tabindex="-1">（2）文件系统缝：<code>ctx.fs</code> 的四层栈 <a class="header-anchor" href="#_2-文件系统缝-ctx-fs-的四层栈" aria-label="Permalink to &quot;（2）文件系统缝：`ctx.fs` 的四层栈&quot;">​</a></h3><p><code>@deepseek-ai/dsh-fs</code> 更是把&quot;缝&quot;用到极致——它把文件栈拆成<strong>四层</strong>（不只是一层三件套）：</p><table tabindex="0"><thead><tr><th>层</th><th>包</th><th>角色</th></tr></thead><tbody><tr><td>tool / executor</td><td><code>dsh-tool-fs</code></td><td>模型可见的 read/write/edit + 渲染；经 <code>ctx.fs</code> 读/写/编辑，派发 <code>fs/*</code> 事件</td></tr><tr><td>policy</td><td><code>dsh-fs-observation-policy</code></td><td>观察态 + 读后编辑 + 版本守卫（经 <code>fs/*</code> 事件，无服务）</td></tr><tr><td>provider contract</td><td><code>dsh-fs</code>（本节）</td><td><code>ctx.fs</code>：执行世界路径、文本 IO、原子性变更原语</td></tr><tr><td>provider</td><td><code>dsh-fs-local</code></td><td>宿主文件系统的实现</td></tr></tbody></table><p>四层里，&quot;接口（provider contract）&quot;与&quot;provider&quot;分离，而它上面还有一层 policy 把&quot;观察 + 版本守卫&quot;这类持久策略挂到 <code>fs/*</code> 事件上，而不必写进 provider。<code>fs-sandbox</code>、<code>fs-e2b</code> 都实现了同一个 <code>ctx.fs</code> 接口，<strong>无需动 policy/tool 两层</strong>——替换 provider，观测策略和模型工具都跟着新的文件系统世界走。</p><p><code>ctx.fs</code> 的接口尤其能看出&quot;执行世界&quot;意识：<code>resolve</code> 返回稳定的 <code>FsTarget</code>，<code>processPath</code> 返回&quot;该 provider 执行世界里可打开的规范路径&quot;，<code>fileUrl</code> 返回规范 file: URI。这几项的存在是因为 <strong>provider 可能不是宿主文件系统</strong>——比如远程 fs-e2b 时，&quot;文件路径&quot;到底该怎么办，由 provider（谁打开这个世界谁就定义了世界的路径）负责。</p><h3 id="_3-安全缝-ctx-sandbox" tabindex="-1">（3）安全缝：<code>ctx.sandbox</code> <a class="header-anchor" href="#_3-安全缝-ctx-sandbox" aria-label="Permalink to &quot;（3）安全缝：`ctx.sandbox`&quot;">​</a></h3><p><code>@deepseek-ai/dsh-sandbox</code> 是&quot;进程隔离&quot;的缝。它是 Process-sandbox Service Definition，只定义<strong>沙箱词汇</strong>与 <code>confinement</code> 契约：</p><ul><li><code>SandboxMode</code>（<code>read-only</code> / <code>workspace-write</code> / <code>danger-full-access</code>，只限文件效果）</li><li><code>SandboxEnforcement</code>（<code>full</code> / <code>partial</code>，按内核 ABI）</li><li><code>SANDBOX_UNAVAILABLE</code>（fail-closed 错误）</li></ul><p>provider <code>dsh-sandbox-local</code> 提供具体后端：Linux 上 <code>bwrap</code>、否则按平台走 Landlock 启动器；macOS 上 <code>sandbox-exec</code>/Seatbelt。Consumer 是 <code>dsh-bash-sandbox</code>（把自己的 spawn <code>[&#39;bash&#39;,&#39;-c&#39;,...]</code> 交给 <code>ctx.sandbox.confine</code> 包裹）。</p><p>沙箱缝有一个设计强调——<strong>&quot;same-world confinement&quot;</strong>。底层的沙箱（bwrap/Landlock/Seatbelt）与宿主共享文件系统与内核，所以它们只是修改&quot;这个世界的路径&quot;；而像容器、微 VM、远程执行器<strong>不是</strong>这个缝的 backend——它们<strong>替换的是整组 Service Provider</strong>（<code>ctx.shell</code>、<code>ctx.fs</code> 一起换）。这就引出下节最重要的&quot;provider 互换&quot;。</p><h2 id="四、provider-互换-整套移动-fs-subprocess-共享一个执行世界" tabindex="-1">四、Provider 互换 = 整套移动：fs / subprocess 共享一个执行世界 <a class="header-anchor" href="#四、provider-互换-整套移动-fs-subprocess-共享一个执行世界" aria-label="Permalink to &quot;四、Provider 互换 = 整套移动：fs / subprocess 共享一个执行世界&quot;">​</a></h2><p>这是 capability 缝里最有信息量的一层。为什么&quot;换一个实现&quot;能&quot;牵一发动全身&quot;？恰恰因为<strong>多个缝在共享一个概念——执行世界</strong>。</p><p>回顾 <code>docs/architecture.md</code> 的原话：</p><blockquote><p>Seams are why one provider swap changes the whole product. Filesystem and subprocess providers share <strong>one execution world</strong>, so pointing them at a remote sandbox moves Bash, PTY, and LSP with them, with no provider forks.</p></blockquote><p>翻译过来：本地一套 <code>fs-local</code> + <code>subprocess-local</code> + 相应普通后端，是共享&quot;宿主文件系统 + 宿主子进程&quot;这一整套&quot;本地执行世界&quot;。若要换成远程沙箱，API 应该做的是：<strong>把 <code>ctx.fs</code> 的 provider、<code>ctx.subprocess</code> 的 provider、以及依赖它们的 bash / PTY / LSP 一起换</strong> ——而不需要为每一个消费者单独 <code>fork</code> 一份代码。</p><p>为什么 fs 和 subprocess 必须一起动？因为<strong>在同一个执行世界里，&quot;文件路径&quot; 与&quot;进程&quot; 是同一个世界的两个面</strong>：一个进程能&quot;打开哪个路径&quot;，取决于它所在世界的文件系统。若 LSP 子进程还在宿主世界、而 fs 已指到远程世界，那个 LSP 就没法&quot;编辑远程的文件&quot;。所以&quot;执行世界&quot;是一个<strong>协调单元</strong>——provider 换一组，事件边界整套移动。</p><p>这就是 <code>docs/capability-seams.md</code> 图谱里 <code>ctx.subprocess</code> 那行看到的现象：它的实现是 <code>subprocess-local</code>、<code>subprocess-e2b</code>，消费者里同时有 <code>bash-local</code>、<code>bash-sandbox</code>、<code>terminal-bash</code>、<code>lsp-stdio</code>、<code>subagent-acp</code>、<code>subagent-codex</code>、<code>subagent-claude-code</code>——<strong>bash、PTY、LSP、各子 agent 后端全都通过 <code>ctx.subprocess</code> 这个单一缝去 spawn</strong>。所以当你把 <code>subprocess</code> 的 provider 从 local 换成 e2b 远程，这些通通跟着一起迁过去，而不用各自写一遍适配。</p><p>三、四节放一起，<code>capability</code> 缝的本质就齐了：</p><blockquote><p><strong>一个缝很少孤立。</strong> 一组缝往往共享一个&quot;执行世界&quot;，所以换的实现要<code>整套移动</code>，而不是逐个修补——这就是&quot;牵一发动全身&quot;的正面含义：<strong>一换全换、干干净净，而不是到处改。</strong></p></blockquote><h2 id="五、各个角色为何要-分开演化-从文档纪律到运行时正确" tabindex="-1">五、各个角色为何要&quot;分开演化&quot;：从文档纪律到运行时正确 <a class="header-anchor" href="#五、各个角色为何要-分开演化-从文档纪律到运行时正确" aria-label="Permalink to &quot;五、各个角色为何要&quot;分开演化&quot;：从文档纪律到运行时正确&quot;">​</a></h2><p>当角色不是一道写死，而是三种能力包，背后是一套<strong>分工纪律</strong>。看 <code>docs/AGENTS.md</code> 与 <code>packages/AGENTS.md</code> 反复的约束就能拼接出一张纪律表：</p><table tabindex="0"><thead><tr><th>目标</th><th>落在 Define</th><th>落在 Provider</th><th>落在 Consumer</th></tr></thead><tbody><tr><td>接口稳定</td><td>定义类型、方法、词汇</td><td>-</td><td>-</td></tr><tr><td>能力按产品可变</td><td>-</td><td>换实现 / 换后端</td><td>-</td></tr><tr><td>与模型交互的 schema</td><td>-</td><td>-</td><td>生成工具 schema、暴露 <code>sandboxMode</code> 能力</td></tr></tbody></table><p>具体说：</p><ol><li><strong>定义不能依赖 Provider</strong>。以 <code>@deepseek-ai/dsh-sandbox</code> 为例，其 README 明确&quot;it depends only on cordis (+ the harness error base), never on a backend&quot;——接口包里绝不 import 任何实现，否则 consumer 就被绑死。</li><li><strong>Consumer 应把 schema/transport 相关都留在自己层</strong>，不要&quot;让一个 Consumer 决定 service&quot;（见 <code>packages/AGENTS.md</code>：Design Service Definitions for all current Consumers，警告&quot;两鼻：一个 public service method 只有一个 internal caller&quot;）。</li><li><strong>一个 service 恰有一个 provider 激活</strong>（win32 上 bash/pwsh 冲突，mount 两个就 fail loud）。这保证&quot;换 provider&quot;是完整的原子操作——不会半套本地、半套远程。</li></ol><p>roles 分开的<strong>最终回报</strong>是 <code>capability-seams.md</code> 那句维护注：「hybrid: services are discovered from Cordis declarations; interface/implementation/consumer roles are classified … with a completeness guard」——<strong>角色的完整性是能被机器检查的</strong>，谁少做了一个角色（接口/实现/消费），组合时就会 fail loud，而不是静默地&quot;只有个头没有身体&quot;。</p><h2 id="六、与三栏对比-终端-agent-的-工具-沙箱-是被硬编码" tabindex="-1">六、与三栏对比：终端 agent 的&quot;工具/沙箱&quot;是被硬编码 <a class="header-anchor" href="#六、与三栏对比-终端-agent-的-工具-沙箱-是被硬编码" aria-label="Permalink to &quot;六、与三栏对比：终端 agent 的&quot;工具/沙箱&quot;是被硬编码&quot;">​</a></h2><p>把 capability 缝与三栏比较（&quot;同能不同构&quot;口径）：</p><table tabindex="0"><thead><tr><th>维度</th><th>OpenCode / Codex / Claude Code</th><th>DeepSeek Harness（<code>dsh</code>）</th></tr></thead><tbody><tr><td>工具（shell/fs）</td><td>作为产品内建，硬编码在代码里</td><td>是<strong>缝</strong>：Definition/Provider/Consumer 三件套</td></tr><tr><td>换沙箱</td><td>改代码、改循环</td><td>换一个 Provider（<code>bash-sandbox</code>）</td></tr><tr><td>让 bash+文件+LSP 一起迁</td><td>要全局改一堆</td><td>只需换共享世界的那一组 provider</td></tr><tr><td>接口可否脱离实现</td><td>混在一起</td><td>明确 Service Definition 独立成包，只依赖接口</td></tr></tbody></table><p>结论很直白：终端编程 agent 把工具与沙箱<strong>当成产品中心的&quot;硬需求&quot;<strong>写进循环；<code>dsh</code> 把它们做成了</strong>可插换的缝</strong>，并且更进一步——共享同一个执行世界的多个缝（fs/subprocess）绑定成一组替换，让&quot;目标环境变了&quot;成了一次性的整套迁移，而不是满仓库到处打补丁。</p><p><strong>它把&quot;加一个能力&quot;从&quot;改 loop&quot;变成了&quot;设计三件套&quot;，又把&quot;换一个环境&quot;从&quot;改整个 loop&quot;变成了&quot;换一组 provider&quot;。</strong> 这正是 <code>dsh</code> 作为&quot;被装配的通用引擎&quot;和终端 agent 作为&quot;产品&quot;的根本差别。</p><h2 id="七、小结与下一步" tabindex="-1">七、小结与下一步 <a class="header-anchor" href="#七、小结与下一步" aria-label="Permalink to &quot;七、小结与下一步&quot;">​</a></h2><p>capability 缝带走了三件事：</p><ol><li><strong>缝 = 三件套</strong>（接口/实现/消费）。完整的缝是三件套一起演化，缺一不算 seam。</li><li><strong>interface 独立成包</strong>，Consumer 只依赖接口不依赖实现——这是&quot;换 Provider 不容易坏&quot;的根因。</li><li><strong>共享世界决定&quot;换一组&quot;</strong>。fs/subprocess 共享一个执行世界，换 provider 时 bash/PTY/LSP 成套迁移，无 provider 分叉。</li></ol><p>到这里，capability 缝把&quot;换实现&quot;这类需求变成&quot;换 Provider&quot;。但还剩一个更魔法的收尾话题，直接踩在第 6 篇的产物上：</p><blockquote><p>工具（Consumer）能换，是因为 Provider 能换；那 <strong>agent 本身能不能被 model 去&quot;改自己&quot;</strong> 呢？——自改/钩子桥，正是把&quot;可插缝&quot;推到了&quot;agent 工具化的极端&quot;。</p></blockquote><p>那就是全专栏的最后两篇：<strong>07 压缩/上下文/子代理</strong>（把压缩也做成可换的缝），以及 <strong>08 自改 / hooks 桥 / 生态</strong>。下一篇先把&quot;长会话怎么活下来&quot;讲清楚——compaction 缝、<code>agent.inject()</code> 与 subagent provider。</p><h2 id="章节小测" tabindex="-1">章节小测 <a class="header-anchor" href="#章节小测" aria-label="Permalink to &quot;章节小测&quot;">​</a></h2>',62)),c(t,{questions:e})])}}});export{p as __pageData,h as default};
